"""Authored educational seeds in the existing BodyParts3D metre coordinates.

These are not measured patient locations and not supplied by WHO. Projection and
regional review are mandatory before publication. Existing 36 seeds are retained
by the final assembly step. Each table follows point-number order, not a spline.
"""
import json
from pathlib import Path

seeds = {}
def series(channel, rows):
    for n, row in enumerate(rows.strip().split(';'), 1):
        values = row.split()
        x, y, z = map(float, values[:3])
        seeds[f'{channel}{n}'] = {'position': [-abs(x), y, z], 'surface': values[3] if len(values) > 3 else 'front'}

